const EQ_POIDS={};
function estimer(o){
  // o : {brand, model, prixNeuf?, annee, km, carburant, boite, etat, options[], entretien, proprios}
  const b=CATALOGUE[o.brand],mdl=b&&b.m[o.model];
  const neuf=num(o.prixNeuf)||(mdl?mdl[0]:0);if(!neuf)return null;
  const cls=b?b.r:2,seg=mdl?mdl[1]:2;
  const yNow=new Date().getFullYear(),age=Math.max(0,yNow-num(o.annee||yNow));
  const d=DECOTE_MODELE[o.brand+"|"+o.model]??{1:0.075,2:0.092,3:0.108}[cls];
  let v=neuf*(age<1?0.88:0.82*Math.pow(1-d,age-1));
  v*=1.18; // hausse des prix de l'occasion depuis 2021
  const attendu=Math.max(1,age)*15000,km=num(o.km);
  v*=Math.min(1.15,Math.max(0.65,1-(km-attendu)/10000*0.025));
  const yr=num(o.annee);
  v*={"Essence":1,"Diesel":yr>=2018?0.97:0.88,"Hybride":1.08,"Électrique":0.9,"GPL":0.86}[o.carburant]||1;
  v*=num(o.coef)||1;
  {const cb=CALIB[o.brand+"|"+o.model];if(cb){const t=Math.max(-0.6,Math.min(1.6,(age-5)/5));v*=cb[0]*Math.pow(cb[1]/cb[0],t)}}
  if(o.boite==="Automatique")v*=seg>=3&&neuf<20000?1.03:1.06;
  v*=(ETATS.find(e=>e[0]===o.etat)||ETATS[1])[3];
  if(o.entretien===false)v*=0.92;
  if(num(o.proprios)>=3)v*=0.95;
  v*=1+Math.min(10,(o.options||[]).reduce((a,l)=>a+(EQ_POIDS[l]!=null?EQ_POIDS[l]:0.5),0))/100;
  v=Math.max(900,v);
  const spread=0.08+Math.min(0.08,age*0.005);
  const r=x=>Math.round(x/50)*50;
  const demande=Math.max(1,Math.min(3,seg-(age>14?1:0)-(km>220000?1:0)));
  return{bas:r(v*(1-spread)),median:r(v),haut:r(v*(1+spread)),demande,delai:{3:"15-30",2:"30-45",1:"45-75"}[demande],neuf,age,catalogue:!!mdl};
}
